module mux4_en (
    input  logic [1:0] sel,
    input  logic [7:0] in0,
    input  logic [7:0] in1,
    input  logic [7:0] in2,
    input  logic [7:0] in3,
    input  logic       en,
    output logic [7:0] out
);

    always_comb begin
        if (!en) begin
            out = 8'h00;
        end else begin
            case (sel)
                2'b00:   out = in0;
                2'b01:   out = in1;
                2'b10:   out = in2;
                2'b11:   out = in3;
                default: out = 8'h00;
            endcase
        end
    end

endmodule
